import{_ as t,o as a,c as o,j as n}from"./chunks/framework.DsyGq6Zh.js";const u=JSON.parse('{"title":"Rethinking Education with AI","description":"Keith Williams explores what learning, judgment, and responsibility mean when AI can produce more of the work.","frontmatter":{"title":"Rethinking Education with AI","description":"Keith Williams explores what learning, judgment, and responsibility mean when AI can produce more of the work."},"headers":[],"relativePath":"research.md","filePath":"research.md"}'),i={name:"research.md"};function r(s,e,h,l,d,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="rethinking-education-with-ai" tabindex="-1">Rethinking Education with AI <a class="header-anchor" href="#rethinking-education-with-ai" aria-label="Permalink to &quot;Rethinking Education with AI&quot;">​</a></h1><p><strong>If AI can produce the assignment, what do we want the student to learn?</strong></p><p>That question keeps coming up in my teaching and in the tools I build. I don&#39;t think we can answer it simply by banning the technology, or by assuming that a better-looking result means better learning.</p><p>This is a set of interests and questions, <strong>not a list of completed experiments or peer-reviewed findings</strong>.</p><h2 id="can-you-use-what-you-learned-somewhere-new" tabindex="-1">Can you use what you learned somewhere new? <a class="header-anchor" href="#can-you-use-what-you-learned-somewhere-new" aria-label="Permalink to &quot;Can you use what you learned somewhere new?&quot;">​</a></h2><p>Someone may finish a project with AI and still struggle to explain or change it. I&#39;d like to understand what kinds of practice help students carry their learning into a new situation.</p><p>A useful study might look at how students explain a decision, debug unfamiliar code, or solve a related problem with and without AI. We&#39;d need fair comparisons and a clear way to judge the results, not just impressions from a successful class session.</p><h2 id="what-should-count-as-evidence-of-learning" tabindex="-1">What should count as evidence of learning? <a class="header-anchor" href="#what-should-count-as-evidence-of-learning" aria-label="Permalink to &quot;What should count as evidence of learning?&quot;">​</a></h2><p>The final program, essay, or design is only part of the picture. The questions a student asks, the tests they choose, and the reasons they give for a decision may tell us something the finished work does not.</p><p>I&#39;m interested in assessment that makes room for explanation, revision, and demonstration. That doesn&#39;t automatically make it better: we also need to ask whether it is fair, consistent, and practical for students and teachers.</p><h2 id="how-do-we-work-with-ai-responsibly" tabindex="-1">How do we work with AI responsibly? <a class="header-anchor" href="#how-do-we-work-with-ai-responsibly" aria-label="Permalink to &quot;How do we work with AI responsibly?&quot;">​</a></h2><p>An assistant that can act across tools creates a different relationship from a chatbot that only suggests text. How much direction does it need? What should it verify? How do we recover when it gets something wrong?</p><p><a href="/life-tracker">Life Tracker</a> is a practical example of keeping work and follow-through visible. <a href="https://github.com/kaw393939/ordo" target="_blank" rel="noreferrer">Ordo</a> explores a broader design for human-directed AI workflows. These are examples to examine, not proof that the approach has been validated.</p><h2 id="start-small-show-the-work" tabindex="-1">Start small, show the work <a class="header-anchor" href="#start-small-show-the-work" aria-label="Permalink to &quot;Start small, show the work&quot;">​</a></h2><p>My instinct is to build a concrete example, make the assumptions visible, and compare it with an alternative. Then ask what the evidence supports and what it doesn&#39;t.</p><p>Any formal study would need an appropriate method, privacy protections, and institutional review where required. Until then, classroom experiences and software projects can help us ask better questions without pretending to settle them.</p><h2 id="ideas-beyond-the-university" tabindex="-1">Ideas beyond the university <a class="header-anchor" href="#ideas-beyond-the-university" aria-label="Permalink to &quot;Ideas beyond the university&quot;">​</a></h2><p>I&#39;m also interested in practical community AI education: helping people understand what these tools can and cannot do, and giving them a useful place to begin. My earlier EverydayAI Newark concept belongs in that category of <strong>ideas to explore</strong>, not established programs.</p><p><a href="/about">More about my background and ideas</a> · <a href="/teaching">How I teach AI</a> · <a href="/#conversation">Start a public conversation</a></p><p><em>Personal research interests. No completed study, institutional endorsement, or formal doctoral appointment is implied.</em></p><h2 id="explore-the-changing-job-market" tabindex="-1">Explore the changing job market <a class="header-anchor" href="#explore-the-changing-job-market" aria-label="Permalink to &quot;Explore the changing job market&quot;">​</a></h2><p><a href="/ai-careers">AI Careers: real jobs, internships and skills</a> connects employer requirements to practical projects you can build and explain. It is a dated research snapshot, not a promise of employment.</p>',22)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
